/**
 * Dashboard Rèn luyện sinh viên
 * Load: DASH_StudentEthic_GetData -> Dashboards/API/StudentEthicDashboardApi.ashx -> ApexCharts
 */
(function () {
    "use strict";
    var API_URL = "/Dashboards/API/StudentEthicDashboardApi.ashx";
    var TEAL = "#1abc9c";
    var BLUE = "#3498db";
    var ORANGE = "#e67e22";
    var YELLOW = "#f1c40f";
    var RED = "#e74c3c";
    var CHART_PALETTE = [TEAL, BLUE, ORANGE, YELLOW, RED, "#9b59b6", "#34495e", "#95a5a6"];
    var TOP_LIMIT = 10;
    var chartInstances = {};
    var eventsBound = false;
    var filterConfig = window.sedDashFilterConfig || {};
    var fullscreenStates = {};
    var TITLE_FONT = "Montserrat, sans-serif";
    var baseChartOpts = {
        fontFamily: TITLE_FONT,
        foreColor: "#475569",
        toolbar: { show: false },
        width: "100%"
    };

    function getChartResponsive(extra) {
        var rules = [
            { breakpoint: 576, options: { chart: { height: 260 }, legend: { fontSize: "11px" } } },
            { breakpoint: 768, options: { chart: { height: 280 } } }
        ];
        var i;
        if (extra && extra.length) {
            for (i = 0; i < extra.length; i++) {
                rules.push(extra[i]);
            }
        }
        return rules;
    }

    function formatNumber(val) {
        var num = parseInt(val, 10);
        if (isNaN(num)) {
            return "0";
        }
        return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function formatRate(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0%";
        }
        return num.toString().replace(".", ",") + "%";
    }

    function formatMark(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0";
        }
        return num.toString().replace(".", ",");
    }

    function getEl(id) {
        return document.getElementById(id);
    }

    function showState(state) {
        var loading = getEl("sedDashStateLoading");
        var error = getEl("sedDashStateError");
        var empty = getEl("sedDashStateEmpty");
        var content = getEl("sedDashContent");
        if (loading) {
            loading.className = state === "loading" ? "sed-dash-state" : "sed-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "sed-dash-state" : "sed-dash-state d-none";
        }
        if (empty) {
            empty.className = state === "empty" ? "sed-dash-state" : "sed-dash-state d-none";
        }
        if (content) {
            content.style.display = (state === "ready" || state === "empty") ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("sedDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function getSelectValue(clientId) {
        if (!clientId) {
            return "";
        }
        var el = document.getElementById(clientId);
        return el ? el.value : "";
    }

    function readFilterConfig() {
        filterConfig = window.sedDashFilterConfig || filterConfig || {};
        return filterConfig;
    }

    function isFilterValueActive(val) {
        return val !== null && val !== undefined && val !== "" && val !== "0" && val !== "-1";
    }

    function getFiltersFromDom() {
        readFilterConfig();
        return {
            yearId: getSelectValue(filterConfig.yearId),
            semester: getSelectValue(filterConfig.semesterId),
            scienceId: getSelectValue(filterConfig.scienceId),
            courseId: getSelectValue(filterConfig.courseId),
            classId: getSelectValue(filterConfig.classId)
        };
    }

    function validateFilters(filters) {
        if (!isFilterValueActive(filters.yearId)) {
            return "Vui lòng chọn Năm học.";
        }
        if (!isFilterValueActive(filters.semester)) {
            return "Vui lòng chọn Học kỳ.";
        }
        return "";
    }

    function fillFilterDropdown(clientId, rows, valueField, textField) {
        var el = document.getElementById(clientId);
        var i;
        var row;
        if (!el) {
            return;
        }
        while (el.options.length > 0) {
            el.remove(0);
        }
        var defaultOpt = document.createElement("option");
        defaultOpt.value = "";
        defaultOpt.text = "--Chọn--";
        el.appendChild(defaultOpt);
        if (!rows || rows.length === 0) {
            return;
        }
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            var opt = document.createElement("option");
            opt.value = row[valueField] !== null && row[valueField] !== undefined ? String(row[valueField]) : "";
            opt.text = row[textField] !== null && row[textField] !== undefined ? String(row[textField]) : "";
            el.appendChild(opt);
        }
    }

    function fillFilterDropdownPreserve(clientId, rows, valueField, textField, preserveValue) {
        var el = document.getElementById(clientId);
        var currentValue = preserveValue !== undefined && preserveValue !== null ? String(preserveValue) : (el ? el.value : "");
        fillFilterDropdown(clientId, rows, valueField, textField);
        if (!el || !isFilterValueActive(currentValue)) {
            return;
        }
        el.value = currentValue;
        if (el.value !== currentValue) {
            el.value = "";
        }
    }

    function loadFilterList(listType, scienceId, courseId, callback) {
        postJson({
            action: "filters",
            listType: listType,
            scienceId: scienceId || "",
            courseId: courseId || ""
        }, function (success, message, data) {
            if (!success) {
                callback(false, message, []);
                return;
            }
            callback(true, "", data && data.items ? data.items : []);
        });
    }

    function refreshClassDropdown(callback) {
        readFilterConfig();
        var scienceId = getSelectValue(filterConfig.scienceId);
        var courseId = getSelectValue(filterConfig.courseId);
        var currentClassId = getSelectValue(filterConfig.classId);
        loadFilterList(3, scienceId, courseId, function (success, message, rows) {
            if (success) {
                fillFilterDropdownPreserve(filterConfig.classId, rows, "ClassID", "ClassName", currentClassId);
            }
            if (typeof callback === "function") {
                callback();
            }
        });
    }

    function onScienceOrCourseFilterChange() {
        refreshClassDropdown(fetchDashboard);
    }

    function onYearSemesterClassFilterChange() {
        fetchDashboard();
    }

    function bindFilterAutoReload() {
        readFilterConfig();
        var yearEl = document.getElementById(filterConfig.yearId);
        var semesterEl = document.getElementById(filterConfig.semesterId);
        var scienceEl = document.getElementById(filterConfig.scienceId);
        var courseEl = document.getElementById(filterConfig.courseId);
        var classEl = document.getElementById(filterConfig.classId);

        if (yearEl) {
            yearEl.addEventListener("change", onYearSemesterClassFilterChange);
        }
        if (semesterEl) {
            semesterEl.addEventListener("change", onYearSemesterClassFilterChange);
        }
        if (classEl) {
            classEl.addEventListener("change", onYearSemesterClassFilterChange);
        }
        if (scienceEl) {
