        if (totalCount > previewCount) {
            noteEl.textContent = "Hiển thị Top " + previewCount + " / " + totalCount + " — bấm phóng to để xem toàn bộ.";
            noteEl.className = "sed-dash-chart-note";
        } else {
            noteEl.textContent = "";
            noteEl.className = "sed-dash-chart-note d-none";
        }
    }

    function sliceTopRows(rows, valueField, limit, desc) {
        var sorted = rows.slice(0);
        sorted.sort(function (a, b) {
            var va = parseFloat(a[valueField]) || 0;
            var vb = parseFloat(b[valueField]) || 0;
            return desc ? vb - va : va - vb;
        });
        return {
            items: limit && sorted.length > limit ? sorted.slice(0, limit) : sorted,
            total: sorted.length
        };
    }

