    function pivotLevelByScience(rows) {
        var scienceMap = {};
        var levelSet = {};
        var sciences = [];
        var levels = [];
        var i;
        var key;
        var row;
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            key = row.ScienceName || row.ScienceID || "";
            if (!scienceMap[key]) {
                scienceMap[key] = {};
                sciences.push(key);
            }
            scienceMap[key][row.LevelName || ""] = parseInt(row.StudentCount, 10) || 0;
            if (!levelSet[row.LevelName || ""]) {
                levelSet[row.LevelName || ""] = true;
                levels.push(row.LevelName || "");
            }
        }
        var seriesList = [];
        for (i = 0; i < levels.length; i++) {
            var levelName = levels[i];
            var data = [];
            var j;
            for (j = 0; j < sciences.length; j++) {
                data.push(scienceMap[sciences[j]][levelName] || 0);
            }
            seriesList.push({ name: levelName, data: data });
        }
        return { labels: sciences, seriesList: seriesList };
    }

