    function fetchDashboard() {
        var filters = getFiltersFromDom();
        var validationMsg = validateFilters(filters);
        if (validationMsg) {
            setErrorMessage(validationMsg);
            showState("error");
            return;
        }
        showState("loading");
        setButtonsLoading(true);
        setErrorMessage("");
        loadDashboardData(function (success, message, data) {
            setButtonsLoading(false);
            if (!success) {
                setErrorMessage(message);
                showState("error");
                return;
            }
            try {
                renderDashboard(data);
            } catch (ex) {
                setErrorMessage("Lỗi xử lý dữ liệu dashboard.");
                showState("error");
            }
        });
    }

    function openFullscreen(stateKey) {
        var overlay = getEl("sedDashFullscreenOverlay");
        var titleEl = getEl("sedDashFullscreenTitle");
        var chartWrap = getEl("sedDashFullscreenChartWrap");
        var state = fullscreenStates[stateKey];
        var options;
        if (!overlay || !state || !state.optionsBuilder) {
            return;
        }
        if (overlay.parentNode !== document.body) {
            document.body.appendChild(overlay);
        }
        if (titleEl) {
            titleEl.textContent = state.title || "Biểu đồ chi tiết";
        }
        options = state.optionsBuilder();
        if (chartWrap && options && options.chart) {
            chartWrap.style.height = options.chart.height + "px";
        }
        renderChart("#sedDashChartPrimaryFullscreen", options, null);
        if (state.layoutMode === "line") {
            overlay.className = "sed-dash-fullscreen sed-dash-fullscreen-line";
        } else if (state.layoutMode === "center") {
            overlay.className = "sed-dash-fullscreen sed-dash-fullscreen-center";
        } else {
            overlay.className = "sed-dash-fullscreen sed-dash-fullscreen-horizontal";
        }
        document.body.style.overflow = "hidden";
        if (chartInstances["#sedDashChartPrimaryFullscreen"]) {
            chartInstances["#sedDashChartPrimaryFullscreen"].windowResizeHandler();
        }
    }

    function closeFullscreen() {
        var overlay = getEl("sedDashFullscreenOverlay");
        var chartWrap = getEl("sedDashFullscreenChartWrap");
        if (!overlay) {
            return;
        }
        overlay.className = "sed-dash-fullscreen d-none";
        document.body.style.overflow = "";
        destroyChart("#sedDashChartPrimaryFullscreen");
        if (chartWrap) {
            chartWrap.style.height = "";
        }
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var btnLoad = getEl("sedDashBtnLoad");
        var btnRefresh = getEl("sedDashBtnRefresh");
        var btnClose = getEl("sedDashBtnCloseFullscreen");

        if (btnLoad) {
            btnLoad.addEventListener("click", fetchDashboard);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", fetchDashboard);
        }
        if (btnClose) {
            btnClose.addEventListener("click", closeFullscreen);
        }
        bindFilterAutoReload();

        var fsButtons = [
            { id: "sedDashBtnFullscreenByClass", key: "byClass" },
            { id: "sedDashBtnFullscreenMarkRange", key: "markRange" },
            { id: "sedDashBtnFullscreenLevelDonut", key: "levelDonut" },
            { id: "sedDashBtnFullscreenByScience", key: "byScience" },
            { id: "sedDashBtnFullscreenByCourse", key: "byCourse" },
            { id: "sedDashBtnFullscreenEvalStatus", key: "evalStatus" },
            { id: "sedDashBtnFullscreenLevelByScience", key: "levelByScience" }
        ];
        var i;
        resetFullscreenButtons();
        for (i = 0; i < fsButtons.length; i++) {
            (function (item) {
                var btn = getEl(item.id);
                if (btn) {
                    btn.addEventListener("click", function () {
                        if (btn.classList.contains("sed-dash-fs-btn-inactive")) {
                            return;
                        }
                        openFullscreen(item.key);
                    });
                }
            })(fsButtons[i]);
        }

        document.addEventListener("keydown", function (e) {
            if (e.key === "Escape") {
                closeFullscreen();
            }
        });

        window.addEventListener("resize", function () {
            var key;
            for (key in chartInstances) {
                if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                    chartInstances[key].windowResizeHandler();
                }
            }
        });
    }

    function initStudentEthicDashboard() {
        if (!getEl("sedDashContent")) {
            return;
        }
        bindEvents();
        fetchDashboard();
    }

    function bootStudentEthicDashboard() {
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initStudentEthicDashboard);
        } else {
            initStudentEthicDashboard();
        }
    }

    bootStudentEthicDashboard();
})();
